def t(language: str, key: str, **kwargs) -> str:
    """Return translated string, falling back to English if not found."""
    lang_dict = _T.get(language, _T["English"])
    text = lang_dict.get(key) or _T["English"].get(key, key)
    if kwargs:
        try:
            text = text.format(**kwargs)
        except (KeyError, IndexError):
            pass
    return text